#!/usr/bin/env bun
/**
 * onboard-centre.ts — Automated Code Ninjas Centre Onboarding
 *
 * Provisions a new centre across Twilio, Retell, Cekura, ChatDash, and Hiya
 * in a single command. Executes 10 sequential steps with rollback-aware logging.
 *
 * Usage:
 *   bun /root/lead-reactivation-github/scripts/onboard-centre.ts \
 *     --name "Leaside" --area-code "647" --country CA \
 *     --owner-name "Sharmila" --owner-email "sharmila@example.com"
 *
 * See onboard-centre.help.md for full documentation.
 */

import { parseArgs } from "util";

// ─────────────────────────────────────────────────────────────
// Configuration
// ─────────────────────────────────────────────────────────────

const TWILIO_SID = "AC[REDACTED-TWILIO-SID]";
const TWILIO_TOKEN = "518f1bbbbd163747a5a8ecb873d6fbd5";
const TWILIO_BASE = "https://api.twilio.com/2010-04-01";

const RETELL_KEY = "key_[REDACTED]";
const RETELL_BASE = "https://api.retellai.com";

const CEKURA_KEY = "c1d54ef4f8e8ed6e5e94033d78b4765060a5a116030e7281a03ed926efb1e2fc";
const CEKURA_BASE = "https://api.cekura.ai";
const CEKURA_PROJECT = 3782;
const CEKURA_PERSONALITY = 693;
const CEKURA_TIER2_CRON_ID = 429;

const SOURCE_AGENT_ID = "agent_0c6c32b61cb506fefb6ac247f4";
const SOURCE_LLM_ID = "llm_44111168b1a2a469f50891b26e34";

const TWILIO_TRUNKING_BASE = "https://trunking.twilio.com/v1";

const SIP_TERMINATION_URI = "xprime.pstn.twilio.com"; // fallback only
const SIP_AUTH_USER = "xprime";
const SIP_AUTH_PASS = "Twiliopass!7";

const N8N_WEBHOOK = "https://xprime17.app.n8n.cloud/webhook/ac45848d-559c-4b66-9058-5d76b8476531";
const N8N_CENTRE_DIR_WEBHOOK = "https://xprime17.app.n8n.cloud/webhook/b4e7c2d1-9f3a-4a5b-8e6d-1c2d3e4f5a6b";

const RESEND_API_KEY = "re_[REDACTED]";
const RESEND_FROM = "Poseidon <onboarding@resend.dev>";
const ONBOARDING_EMAIL_TO = "scott.james@codeninjas.com";
const KB_REFERENCE_URL = "https://docs.google.com/document/d/1QTvkO1d72KYIi2ALtPEIrOASsbxggxeyCRiS1rWK3Ek/edit?usp=sharing";

// Metric IDs used in scenarios
const METRIC_EXPECTED_OUTCOME = 118041;
const METRIC_TOUR_BOOKING = 118268;
const METRIC_NATURAL_FLOW = 118273;
const METRIC_LOCATION_ACCURACY = 119652;

const CN_SERVICES_BASE = "https://services.codeninjas.com/api/v1";
const CN_SITEMAP_URL = "https://www.codeninjas.com/sitemap.xml";

// ─────────────────────────────────────────────────────────────
// CLI Argument Parsing
// ─────────────────────────────────────────────────────────────

const HELP_TEXT = `
onboard-centre — Automate full Code Ninjas centre onboarding

USAGE:
  bun onboard-centre.ts --name <name> [options]

REQUIRED:
  --name          Centre name (e.g., "Riverside", "Leaside")

OPTIONS:
  --area-code     Twilio area code (auto-discovered from codeninjas.com if omitted)
  --country       Country code: CA or US (auto-discovered if omitted)
  --owner-name    Centre owner first name (for ChatDash client)
  --owner-email   Centre owner email (for ChatDash login)
  --dry-run       Show what would happen without executing API calls
  --help, -h      Show this help message

AUTO-DISCOVERY:
  When --area-code is omitted, the script searches codeninjas.com for the
  centre, discovers its URL code (e.g., ct-riverside), address, and phone
  number, then derives the area code and country automatically.

  The centre code is output in the summary for populating the centre
  directory spreadsheet.

EXAMPLES:
  # Auto-discover everything (recommended)
  bun onboard-centre.ts --name "Riverside"

  # Override area code and country manually
  bun onboard-centre.ts --name "Leaside" --area-code "647" --country CA

  # Dry run — preview without executing
  bun onboard-centre.ts --name "Riverside" --dry-run

STEPS EXECUTED:
  0. Discover  — Search codeninjas.com for centre details
  1. Twilio    — Sub-account + phone + SIP trunk
  2. Retell    — Create LLM copy (with centre name hardcoded)
  3. Retell    — Clone agent
  4. Retell    — Import phone number + link to agent
  5. Cekura    — Create test agent
  6. Cekura    — Create Tier 2 scenarios (Location Verify + Happy Path)
  7. Cekura    — Print Tier 2 cron update instructions
  8. ChatDash  — Print manual setup instructions
  9. Google    — Write centre directory row via n8n webhook
  10. Email    — Send client onboarding email (auto-populated)
  11. Hiya     — Print branded caller ID instructions
  12. Checklist — Send internal manual-items email to Scott
  13. Summary  — Print all created resource IDs
`;

const { values } = parseArgs({
  args: Bun.argv.slice(2),
  options: {
    name: { type: "string" },
    "area-code": { type: "string" },
    country: { type: "string" },
    "owner-name": { type: "string" },
    "owner-email": { type: "string" },
    "dry-run": { type: "boolean", default: false },
    help: { type: "boolean", short: "h", default: false },
  },
});

if (values.help) {
  console.log(HELP_TEXT);
  process.exit(0);
}

const centreName = values.name;
let areaCode = values["area-code"];
let country = values.country ? values.country.toUpperCase() : undefined;
const ownerName = values["owner-name"] ?? "";
const ownerEmail = values["owner-email"] ?? "";
const dryRun = values["dry-run"] ?? false;

if (!centreName) {
  console.error("\x1b[31mError: --name is required\x1b[0m");
  console.error('Usage: bun onboard-centre.ts --name "Riverside"');
  process.exit(1);
}
if (country && !["CA", "US"].includes(country)) {
  console.error(`\x1b[31mError: --country must be CA or US, got "${country}"\x1b[0m`);
  process.exit(1);
}

// ─────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────

interface CentreDiscovery {
  centreCode: string;       // e.g., "ct-riverside"
  city: string;             // e.g., "Riverside"
  state: string;            // e.g., "CT"
  stateName: string;        // e.g., "Connecticut"
  country: string;          // "US" or "CA"
  postalCode: string;       // e.g., "06878"
  areaCode: string;         // e.g., "203"
  phone: string;            // e.g., "2036338000"
  address: string;          // e.g., "1171 E. Putnam Avenue"
  email: string;            // e.g., "riversidect@codeninjas.com"
  url: string;              // e.g., "https://www.codeninjas.com/ct-riverside"
}

interface OnboardingState {
  discovery: CentreDiscovery | null;
  // Twilio sub-account
  subAccountSid: string | null;
  subAccountToken: string | null;
  twilioNumber: string | null;
  twilioSid: string | null;
  trunkDomain: string | null;
  trunkSid: string | null;
  // Retell
  retellLlmId: string | null;
  retellAgentId: string | null;
  retellPhoneId: string | null;
  // Cekura
  cekuraAgentId: number | null;
  cekuraScenarioLocId: number | null;
  cekuraScenarioHpId: number | null;
}

interface TwilioNumber {
  phone_number: string;
  friendly_name: string;
  locality: string;
  region: string;
}

// ─────────────────────────────────────────────────────────────
// Logging Utilities
// ─────────────────────────────────────────────────────────────

const GREEN = "\x1b[32m";
const RED = "\x1b[31m";
const YELLOW = "\x1b[33m";
const CYAN = "\x1b[36m";
const BOLD = "\x1b[1m";
const DIM = "\x1b[2m";
const RESET = "\x1b[0m";

function stepHeader(num: number, title: string): void {
  console.log(`\n${BOLD}${CYAN}[${"0".repeat(2 - String(num).length)}${num}]${RESET} ${BOLD}${title}${RESET}`);
}

function success(msg: string): void {
  console.log(`  ${GREEN}OK${RESET} ${msg}`);
}

function fail(msg: string): void {
  console.log(`  ${RED}FAIL${RESET} ${msg}`);
}

function warn(msg: string): void {
  console.log(`  ${YELLOW}WARN${RESET} ${msg}`);
}

function info(msg: string): void {
  console.log(`  ${DIM}${msg}${RESET}`);
}

function dryLog(msg: string): void {
  console.log(`  ${YELLOW}[DRY-RUN]${RESET} ${msg}`);
}

// ─────────────────────────────────────────────────────────────
// HTTP Helpers
// ─────────────────────────────────────────────────────────────

async function twilioGet<T>(path: string): Promise<T> {
  const url = `${TWILIO_BASE}/Accounts/${TWILIO_SID}${path}`;
  const auth = Buffer.from(`${TWILIO_SID}:${TWILIO_TOKEN}`).toString("base64");
  const res = await fetch(url, {
    headers: { Authorization: `Basic ${auth}` },
  });
