async function step10_onboardingEmail(state: OnboardingState): Promise<void> {
  stepHeader(10, "Client Onboarding Email");

  let centreCode = state.discovery?.centreCode ?? "";
  let director = ownerName;

  // Look up director name and centre code from the sheet if not already known
  if (!director || !centreCode) {
    try {
      info("Looking up director name from centre directory sheet...");
      const csvUrl = `https://docs.google.com/spreadsheets/d/${CENTRE_LOOKUP_SHEET}/gviz/tq?tqx=out:csv`;
      const csvRes = await fetch(csvUrl);
      if (csvRes.ok) {
        const csv = await csvRes.text();
        const rows = csv.split("\n");
        for (const row of rows) {
          // Parse CSV fields properly (handles quoted values)
          const cols: string[] = [];
          let current = "";
          let inQuotes = false;
          for (const ch of row) {
            if (ch === '"') { inQuotes = !inQuotes; continue; }
            if (ch === ',' && !inQuotes) { cols.push(current.trim()); current = ""; continue; }
            current += ch;
          }
          cols.push(current.trim());

          // Match on location_name (column 3) — case-insensitive
          const locationName = cols[3] ?? "";
          if (locationName.toLowerCase() === centreName.toLowerCase()) {
            // Column 0 = centre_id, Column 8 = Director
            if (!centreCode && cols[0]) {
              centreCode = cols[0];
              info(`Found centre code: ${centreCode}`);
            }
            const dirCol = cols[8] ?? "";
            if (!director && dirCol) {
              director = dirCol.split(" ")[0]; // First name only for salutation
              info(`Found director: ${dirCol} (using "${director}" for salutation)`);
            }
            break;
          }
        }
      }
    } catch {
      info("Could not look up from sheet — using available data");
    }
  }

  // Final fallback for centre code
  if (!centreCode) {
    centreCode = centreName.toLowerCase().replace(/\s+/g, "-");
  }

  const fromNumber = (state.twilioNumber ?? "").replace("+", "");
  const subject = `Code Ninjas ${centreName} — Getting Started`;
  const html = buildOnboardingEmailHtml(director, centreCode, centreName, fromNumber);

  if (dryRun) {
    dryLog(`Would send onboarding email to ${ONBOARDING_EMAIL_TO}`);
    dryLog(`Subject: ${subject}`);
    dryLog(`Salutation: "Hi ${director || "there"}"`);
    dryLog(`Centre code in email: ${centreCode}`);
    dryLog(`Forwarding address: scott.james1717+${centreCode}@gmail.com`);
    return;
  }

  info(`Sending onboarding email to ${ONBOARDING_EMAIL_TO}...`);

  const res = await fetch("https://api.resend.com/emails", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${RESEND_API_KEY}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      from: RESEND_FROM,
      to: [ONBOARDING_EMAIL_TO],
      subject,
      html,
    }),
  });

  if (!res.ok) {
    throw new Error(`Resend API failed: ${res.status} ${await res.text()}`);
  }

  const result = await res.json() as { id: string };
  ok(`Onboarding email sent (ID: ${result.id})`);
  info(`Forward to the centre director when ready`);
}

