async function step12_internalChecklist(state: OnboardingState): Promise<void> {
  stepHeader(12, "Internal Checklist Email");

  const subject = `[ACTION] Code Ninjas ${centreName} — Manual Onboarding Checklist`;
  const html = buildInternalChecklistHtml(state);

  if (dryRun) {
    dryLog(`Would send internal checklist email to ${ONBOARDING_EMAIL_TO}`);
    dryLog(`Subject: ${subject}`);
    dryLog(`Items: Cekura Cron, ChatDash, Hiya`);
    return;
  }

  info(`Sending internal checklist email to ${ONBOARDING_EMAIL_TO}...`);

  const res = await fetch("https://api.resend.com/emails", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${RESEND_API_KEY}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      from: RESEND_FROM,
      to: [ONBOARDING_EMAIL_TO],
      subject,
      html,
    }),
  });

  if (!res.ok) {
    throw new Error(`Resend API failed: ${res.status} ${await res.text()}`);
  }

  const result = await res.json() as { id: string };
  ok(`Internal checklist email sent (ID: ${result.id})`);
}

