function step13_summary(state: OnboardingState): void {
  stepHeader(13, "Onboarding Summary");

  const pad = (s: string, len: number): string => s.padEnd(len);
  const w = 56;
  const rule = "=".repeat(w);
  const line = (label: string, value: string): string => {
    const content = `  ${pad(label, 22)} ${value}`;
    return `  ${content}`;
  };

  const d = state.discovery;
  console.log(`
  ${GREEN}${BOLD}${rule}${RESET}
  ${GREEN}${BOLD}  ONBOARDING COMPLETE: Code Ninjas ${centreName}${RESET}
  ${GREEN}${BOLD}${rule}${RESET}
${d ? `${line("Centre Code:", d.centreCode)}
${line("City:", `${d.city}, ${d.state}`)}
${line("Address:", d.address)}
${line("Country:", d.country)}
${line("Area Code:", d.areaCode)}
` : ""}${line("Twilio Sub-Account:", state.subAccountSid ?? "FAILED")}
${line("Twilio Number:", state.twilioNumber ?? "FAILED")}
${line("Twilio SID:", state.twilioSid ?? "FAILED")}
${line("SIP Trunk:", state.trunkDomain ?? "FAILED")}
${line("Retell LLM:", state.retellLlmId ?? "FAILED")}
${line("Retell Agent:", state.retellAgentId ?? "FAILED")}
