async function main(): Promise<void> {
  console.log(`\n${BOLD}${CYAN}===============================================${RESET}`);
  console.log(`${BOLD}${CYAN} Code Ninjas Centre Onboarding: ${centreName}${RESET}`);
  console.log(`${BOLD}${CYAN}===============================================${RESET}`);
  if (ownerName) console.log(`  Owner: ${ownerName} <${ownerEmail}>`);
  if (dryRun) console.log(`  ${YELLOW}${BOLD}MODE: DRY RUN${RESET}`);

  const state: OnboardingState = {
    discovery: null,
    subAccountSid: null,
    subAccountToken: null,
    twilioNumber: null,
    twilioSid: null,
    trunkDomain: null,
    trunkSid: null,
    retellLlmId: null,
    retellAgentId: null,
    retellPhoneId: null,
    cekuraAgentId: null,
    cekuraScenarioLocId: null,
    cekuraScenarioHpId: null,
  };

  const completed: string[] = [];
  const failed: string[] = [];

  // Step 0: Discover centre details if area-code not provided
  if (!areaCode) {
    try {
      const discovery = await step0_discover(centreName);
      state.discovery = discovery;
      areaCode = discovery.areaCode;
      country = country ?? discovery.country;
      completed.push("Discovery");
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      fail(msg);
      console.log(`\n${RED}${BOLD}Discovery failed. Provide --area-code and --country manually.${RESET}`);
      process.exit(1);
    }
  } else {
    country = country ?? "CA";
    info(`Using manual area code: ${areaCode}, country: ${country}`);
  }

  console.log(`  Country: ${country} | Area Code: ${areaCode}`);

  // Steps 1-6 are API-dependent and sequential
  const steps: Array<{
    name: string;
    fn: (state: OnboardingState) => Promise<void> | void;
  }> = [
    { name: "Twilio Provision", fn: step1_twilioProvision },
    { name: "Retell LLM", fn: step2_retellLlm },
    { name: "Retell Agent", fn: step3_retellAgent },
    { name: "Retell Phone Import", fn: step4_retellPhone },
    { name: "Cekura Agent", fn: step5_cekuraAgent },
    { name: "Cekura Scenarios", fn: step6_cekuraScenarios },
  ];

  for (const step of steps) {
    try {
      await step.fn(state);
      completed.push(step.name);
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      fail(msg);
      failed.push(step.name);

      // Report partial progress and bail
      console.log(`\n${RED}${BOLD}Onboarding ABORTED at step: ${step.name}${RESET}`);
      console.log(`\n  ${GREEN}Completed:${RESET} ${completed.join(", ") || "none"}`);
      console.log(`  ${RED}Failed:${RESET} ${failed.join(", ")}`);

      if (completed.length > 0) {
        console.log(`\n  ${YELLOW}Partial resources created (may need manual cleanup):${RESET}`);
        if (state.subAccountSid) console.log(`    Twilio Sub-Account: ${state.subAccountSid}`);
        if (state.twilioNumber) console.log(`    Twilio Phone: ${state.twilioNumber} (SID: ${state.twilioSid})`);
        if (state.trunkSid) console.log(`    Twilio Trunk: ${state.trunkSid} (${state.trunkDomain})`);
        if (state.retellLlmId) console.log(`    Retell LLM: ${state.retellLlmId}`);
        if (state.retellAgentId) console.log(`    Retell Agent: ${state.retellAgentId}`);
        if (state.retellPhoneId) console.log(`    Retell Phone: ${state.retellPhoneId}`);
        if (state.cekuraAgentId) console.log(`    Cekura Agent: ${state.cekuraAgentId}`);
      }

      process.exit(1);
    }
  }

  // Step 7-8 are informational (no API calls), always succeed
  step7_cekuraCron(state);
  step8_chatDash(state);

  // Step 9 writes to Google Sheet via n8n webhook
  try {
    await step9_googleSheet(state);
    completed.push("Google Sheet");
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    fail(`Google Sheet update failed: ${msg}`);
    console.log(`  ${YELLOW}Manual fallback:${RESET} Update sheet at https://docs.google.com/spreadsheets/d/${CENTRE_LOOKUP_SHEET}/edit`);
  }

  // Step 10 sends the client onboarding email
  try {
    await step10_onboardingEmail(state);
    completed.push("Onboarding Email");
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    fail(`Onboarding email failed: ${msg}`);
  }

  // Step 11 is informational, always succeeds
  step11_hiya(state);

  // Step 12 sends internal checklist email
  try {
    await step12_internalChecklist(state);
    completed.push("Internal Checklist Email");
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    fail(`Internal checklist email failed: ${msg}`);
  }

  // Step 13 is the summary
  step13_summary(state);
}

main().catch((err) => {
  console.error(`\n${RED}${BOLD}Fatal error:${RESET}`, err);
  process.exit(1);
});

