const CENTRE_LOOKUP_SHEET = "1wQAdX3frfxCHK0HmGCKRpzmOx7SFaLP-3nn7AEc0GK0";

async function step9_googleSheet(state: OnboardingState): Promise<void> {
  stepHeader(9, "Google Sheet - Centre Directory");

  const fromNumber = (state.twilioNumber ?? "").replace("+", "");
  const agentId = state.retellAgentId ?? "";
  const centreCode = state.discovery?.centreCode ?? centreName.toLowerCase().replace(/\s+/g, "-");
  const centreEmail = state.discovery?.email ?? "";
  const timezone = (country === "CA") ? "America/Toronto" : "America/New_York";

  const payload = {
    centre_id: centreCode,
    timezone,
    enabled: "TRUE",
    location_name: centreName,
    from_number: fromNumber,
    testing: "TRUE",
    test_number: "9059672357",
    centre_email: centreEmail,
    director: ownerName ?? "",
    agent_id: agentId,
    knowledge_base: "https://docs.google.com/document/d/1QTvkO1d72KYIi2ALtPEIrOASsbxggxeyCRiS1rWK3Ek/edit?usp=sharing",
  };

  if (dryRun) {
    info("DRY RUN — would write to Centre Directory sheet:");
    console.log(`    ${JSON.stringify(payload, null, 2).replace(/\n/g, "\n    ")}`);
    return;
  }

  info(`Writing to Centre Directory sheet via n8n webhook...`);
  const res = await fetch(N8N_CENTRE_DIR_WEBHOOK, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
