// ─────────────────────────────────────────────────────────────
// Step 0: Discover Centre from codeninjas.com
// ─────────────────────────────────────────────────────────────

async function step0_discover(name: string): Promise<CentreDiscovery> {
  stepHeader(0, "Discover Centre from codeninjas.com");

  // Step 0a: Fetch sitemap and search for the centre slug
  info(`Fetching sitemap from ${CN_SITEMAP_URL}...`);
  const sitemapRes = await fetch(CN_SITEMAP_URL, {
    headers: { "User-Agent": "Mozilla/5.0 (compatible; onboard-centre/1.0)" },
  });
  if (!sitemapRes.ok) {
    throw new Error(`Failed to fetch sitemap: ${sitemapRes.status}`);
  }
  const sitemapXml = await sitemapRes.text();

  // Extract all location URLs matching the centre name (case-insensitive)
  const nameLower = name.toLowerCase().replace(/\s+/g, "-");
  const urlPattern = new RegExp(
    `https://www\\.codeninjas\\.com/([a-z]{2})-${nameLower}(?=[/<])`,
    "gi"
  );
  const matches = [...new Set(
    Array.from(sitemapXml.matchAll(urlPattern), (m) => m[0])
  )];

  if (matches.length === 0) {
    // Try partial match — the name might be part of a longer slug
    const partialPattern = new RegExp(
      `https://www\\.codeninjas\\.com/([a-z]{2}-[^/<"]*${nameLower}[^/<"]*)(?=[/<])`,
      "gi"
    );
    const partialMatches = [...new Set(
      Array.from(sitemapXml.matchAll(partialPattern), (m) => m[0])
    )];
    if (partialMatches.length > 0) {
      info(`No exact match. Partial matches found:`);
      for (const u of partialMatches) info(`  ${u}`);
      throw new Error(
        `No exact match for "${name}". Did you mean one of the above? ` +
        `Try using the full centre name from the URL.`
      );
    }
    throw new Error(
      `Centre "${name}" not found in codeninjas.com sitemap. ` +
      `Check spelling or provide --area-code manually.`
    );
  }

  // Deduplicate to base URLs (strip subpages)
  const baseUrls = [...new Set(
    matches.map((u) => {
      const path = new URL(u).pathname;
      // Base path is /{state}-{name} — no further slashes
      const parts = path.split("/").filter(Boolean);
      return `https://www.codeninjas.com/${parts[0]}`;
    })
  )];

  if (baseUrls.length > 1) {
    info(`Multiple locations found for "${name}":`);
    for (const u of baseUrls) info(`  ${u}`);
    throw new Error(
      `Multiple locations match "${name}": ${baseUrls.join(", ")}. ` +
      `Specify the full slug or provide --area-code and --country manually.`
    );
  }

  const centreUrl = baseUrls[0];
  const cnSlug = new URL(centreUrl).pathname.slice(1); // e.g., "ct-riverside"
  success(`Found centre: ${centreUrl} (code: ${cnSlug})`);

  // Step 0b: Fetch facility details from services API
  info(`Fetching facility profile from services API...`);
  const profileUrl = `${CN_SERVICES_BASE}/facility/profile/slug/${cnSlug}`;
  const profileRes = await fetch(profileUrl);
  if (!profileRes.ok) {
    throw new Error(`Services API returned ${profileRes.status} for slug "${cnSlug}"`);
  }
  const profile = await profileRes.json() as Record<string, unknown>;

  const phone = String(profile.phone ?? "");
  const discoveredAreaCode = phone.length >= 10 ? phone.slice(0, 3) : "";
  const discoveredCountry = String(profile.countryCode ?? "US");

  const discovery: CentreDiscovery = {
    centreCode: cnSlug,
    city: String(profile.city ?? ""),
    state: String(profile.stateAbbreviation ?? ""),
    stateName: String(profile.stateName ?? ""),
    country: discoveredCountry,
    postalCode: String(profile.postalCode ?? ""),
    areaCode: discoveredAreaCode,
    phone,
    address: String(profile.streetAddress1 ?? ""),
    email: String(profile.emailAddress ?? ""),
    url: centreUrl,
  };

  success(`City: ${discovery.city}, ${discovery.state}`);
  success(`Address: ${discovery.address}, ${discovery.postalCode}`);
  success(`Phone: ${discovery.phone} (area code: ${discovery.areaCode})`);
  success(`Country: ${discovery.country}`);
  success(`Centre code: ${discovery.centreCode}`);

  return discovery;
}

// ─────────────────────────────────────────────────────────────
// Step 1: Twilio — Sub-Account + Phone + SIP Trunk
// ─────────────────────────────────────────────────────────────

async function step1_twilioProvision(state: OnboardingState): Promise<void> {
  stepHeader(1, "Twilio - Sub-Account + Phone + SIP Trunk");

  const slugName = centreName.toLowerCase().replace(/\s+/g, "-");
  const trunkDomain = `${slugName}-cnkb.pstn.twilio.com`;

  if (dryRun) {
    dryLog(`Would create sub-account "Code Ninjas ${centreName}"`);
    dryLog(`Would search for ${country} numbers with area code ${areaCode}`);
    dryLog(`Would purchase first available and name it "CNKB-${centreName}"`);
    dryLog(`Would create SIP credential list + credential (${slugName})`);
    dryLog(`Would create SIP trunk: ${trunkDomain}`);
    dryLog(`Would add origination URI: sip:sip.retellai.com`);
    dryLog(`Would associate credential list with trunk`);
    dryLog(`Would link phone number to trunk`);
    state.subAccountSid = "AC_dry_run_sub_sid";
    state.subAccountToken = "dry_run_sub_token";
    state.twilioNumber = `+${areaCode}5550100`;
    state.twilioSid = "PN_dry_run_sid";
    state.trunkDomain = trunkDomain;
    state.trunkSid = "TK_dry_run_trunk_sid";
    return;
  }

  // 1a. Create sub-account (top-level endpoint, not nested under parent account)
  info(`Creating sub-account "Code Ninjas ${centreName}"...`);
  const subAccountRes = await fetch(`${TWILIO_BASE}/Accounts.json`, {
    method: "POST",
    headers: {
      Authorization: `Basic ${Buffer.from(`${TWILIO_SID}:${TWILIO_TOKEN}`).toString("base64")}`,
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body: new URLSearchParams({ FriendlyName: `Code Ninjas ${centreName}` }).toString(),
  });
  if (!subAccountRes.ok) {
    const text = await subAccountRes.text();
    throw new Error(`Twilio POST /Accounts.json → ${subAccountRes.status}: ${text}`);
  }
  const subAccount = await subAccountRes.json() as { sid: string; auth_token: string };
  state.subAccountSid = subAccount.sid;
  state.subAccountToken = subAccount.auth_token;
  success(`Sub-account: ${subAccount.sid}`);

  const subSid = subAccount.sid;
  const subToken = subAccount.auth_token;

  // 1b. Search and purchase phone number on sub-account
  info(`Searching for ${country} numbers in area code ${areaCode}...`);
  const searchPath = `/AvailablePhoneNumbers/${country}/Local.json?AreaCode=${areaCode}&Limit=5`;
  const searchResult = await subTwilioGet<{ available_phone_numbers: TwilioNumber[] }>(subSid, subToken, searchPath);
  const available = searchResult.available_phone_numbers;

  if (!available || available.length === 0) {
    throw new Error(`No available numbers found for area code ${areaCode} in ${country}`);
  }

  info(`Found ${available.length} available number(s):`);
  for (const num of available) {
    info(`  ${num.phone_number} (${num.locality || "unknown"}, ${num.region || "unknown"})`);
  }

  const chosen = available[0];
  info(`Purchasing ${chosen.phone_number}...`);
  const purchased = await subTwilioPost<{ sid: string; phone_number: string }>(
    subSid, subToken,
    "/IncomingPhoneNumbers.json",
    { PhoneNumber: chosen.phone_number, FriendlyName: `CNKB-${centreName}` }
  );
  state.twilioNumber = purchased.phone_number;
  state.twilioSid = purchased.sid;
  success(`Purchased ${purchased.phone_number} (SID: ${purchased.sid})`);

  // 1c. Create SIP credential list
  info("Creating SIP credential list...");
  const credList = await subTwilioPost<{ sid: string }>(
    subSid, subToken,
    "/SIP/CredentialLists.json",
    { FriendlyName: `${centreName} CNKB Creds` }
  );
  const credListSid = credList.sid;
  success(`Credential list: ${credListSid}`);

  // 1d. Create SIP credential
  info("Creating SIP credential...");
  await subTwilioPost<{ sid: string }>(
    subSid, subToken,
    `/SIP/CredentialLists/${credListSid}/Credentials.json`,
    { Username: slugName, Password: SIP_AUTH_PASS }
  );
  success(`Credential created: ${slugName}`);

  // 1e. Create SIP trunk
  info(`Creating SIP trunk: ${trunkDomain}...`);
  const trunk = await trunkingPost<{ sid: string }>(
    subSid, subToken,
    "/Trunks",
    { FriendlyName: `CNKB-${centreName}`, DomainName: trunkDomain }
  );
  state.trunkSid = trunk.sid;
  state.trunkDomain = trunkDomain;
  success(`Trunk: ${trunk.sid} (${trunkDomain})`);

  // 1f. Add origination URI (Retell SIP endpoint)
  info("Adding origination URI: sip:sip.retellai.com...");
  await trunkingPost<{ sid: string }>(
    subSid, subToken,
    `/Trunks/${trunk.sid}/OriginationUrls`,
    {
      FriendlyName: "Retell AI",
      SipUrl: "sip:sip.retellai.com",
      Priority: "1",
      Weight: "1",
      Enabled: "true",
    }
  );
  success("Origination URI added");

  // 1g. Associate credential list with trunk
  info("Associating credential list with trunk...");
  await trunkingPost<{ sid: string }>(
    subSid, subToken,
    `/Trunks/${trunk.sid}/CredentialLists`,
    { CredentialListSid: credListSid }
  );
  success("Credential list associated");

  // 1h. Link phone number to trunk
  info("Linking phone number to trunk...");
  await trunkingPost<{ sid: string }>(
    subSid, subToken,
    `/Trunks/${trunk.sid}/PhoneNumbers`,
    { PhoneNumberSid: purchased.sid }
  );
  success(`Phone ${purchased.phone_number} linked to trunk`);
}

// ─────────────────────────────────────────────────────────────
// Step 2: Retell — Create LLM Copy
// ─────────────────────────────────────────────────────────────

async function step2_retellLlm(state: OnboardingState): Promise<void> {
  stepHeader(2, "Retell - Create LLM Copy");

  if (dryRun) {
    dryLog(`Would GET source LLM ${SOURCE_LLM_ID}`);
    dryLog(`Would replace {{LOCATION_NAME}} with "${centreName}" in general_prompt and begin_message`);
    dryLog("Would POST /create-retell-llm with modified copy");
    state.retellLlmId = "llm_dry_run_id";
    return;
  }

  info(`Fetching source LLM ${SOURCE_LLM_ID}...`);
  const sourceLlm = await retellGet<Record<string, unknown>>(`/get-retell-llm/${SOURCE_LLM_ID}`);

  // Strip fields that cannot be set on create
  const stripped = { ...sourceLlm };
  delete stripped.llm_id;
  delete stripped.version;
  delete stripped.last_modification_timestamp;
  delete stripped.is_published;

  // Replace template variable with hardcoded centre name
  if (typeof stripped.general_prompt === "string") {
    stripped.general_prompt = stripped.general_prompt.replace(/\{\{LOCATION_NAME\}\}/g, centreName);
    info(`Replaced {{LOCATION_NAME}} in general_prompt`);
  }
  if (typeof stripped.begin_message === "string") {
    stripped.begin_message = stripped.begin_message.replace(/\{\{LOCATION_NAME\}\}/g, centreName);
    info(`Replaced {{LOCATION_NAME}} in begin_message`);
  }

  info("Creating new LLM...");
  const newLlm = await retellPost<{ llm_id: string }>("/create-retell-llm", stripped);

  state.retellLlmId = newLlm.llm_id;
  success(`Created LLM ${newLlm.llm_id}`);
}

// ─────────────────────────────────────────────────────────────
// Step 3: Retell — Clone Agent
// ─────────────────────────────────────────────────────────────

async function step3_retellAgent(state: OnboardingState): Promise<void> {
  stepHeader(3, "Retell - Clone Agent");

  if (dryRun) {
    dryLog(`Would GET source agent ${SOURCE_AGENT_ID}`);
    dryLog(`Would create clone named "CNKB-${centreName}" with LLM ${state.retellLlmId}`);
    state.retellAgentId = "agent_dry_run_id";
    return;
  }

  info(`Fetching source agent ${SOURCE_AGENT_ID}...`);
  const sourceAgent = await retellGet<Record<string, unknown>>(`/get-agent/${SOURCE_AGENT_ID}`);

  // Strip fields that cannot be set on create
  const stripped = { ...sourceAgent };
  delete stripped.agent_id;
  delete stripped.version;
  delete stripped.is_published;
  delete stripped.last_modification_timestamp;
  delete stripped.version_title;

  // Set the new agent's identity
  stripped.agent_name = `CNKB-${centreName}`;

  // Point to the newly created LLM at version 0 (fresh LLM = version 0 is current)
  stripped.response_engine = {
    type: "retell-llm",
    llm_id: state.retellLlmId,
    version: 0,
  };

  // Remove webhook — will be set after ChatDash agent creation
  delete stripped.webhook_url;

  info("Creating agent clone...");
  const newAgent = await retellPost<{ agent_id: string }>("/create-agent", stripped);

  state.retellAgentId = newAgent.agent_id;
  success(`Created agent ${newAgent.agent_id} (CNKB-${centreName})`);
}

// ─────────────────────────────────────────────────────────────
// Step 4: Retell — Import Phone Number
// ─────────────────────────────────────────────────────────────

async function step4_retellPhone(state: OnboardingState): Promise<void> {
  stepHeader(4, "Retell - Import Phone Number");

  const terminationUri = state.trunkDomain ?? SIP_TERMINATION_URI;

  if (dryRun) {
    dryLog(`Would import ${state.twilioNumber} to Retell via SIP trunk ${terminationUri}`);
    dryLog(`Would set outbound agent to ${state.retellAgentId}`);
    state.retellPhoneId = "phone_dry_run_id";
    return;
  }

  info(`Importing ${state.twilioNumber} to Retell (trunk: ${terminationUri})...`);

  const result = await retellPost<{ phone_number: string; phone_number_id?: string }>(
    "/import-phone-number",
    {
      phone_number: state.twilioNumber,
      termination_uri: terminationUri,
      nickname: centreName,
      outbound_agent_id: state.retellAgentId,
      sip_trunk_auth_username: SIP_AUTH_USER,
      sip_trunk_auth_password: SIP_AUTH_PASS,
    }
  );

  state.retellPhoneId = result.phone_number_id ?? result.phone_number;
  success(`Imported ${state.twilioNumber} (ID: ${state.retellPhoneId})`);
}

