async function step6_cekuraScenarios(state: OnboardingState): Promise<void> {
  stepHeader(6, "Cekura - Create Tier 2 Scenarios");

  // Location Verification scenario
  const locPayload = {
    name: `Location Verification - ${centreName}`,
    agent: state.cekuraAgentId,
    project: CEKURA_PROJECT,
    personality: CEKURA_PERSONALITY,
    tags: ["tier2", "location-verify"],
    first_message: "Hello",
    instructions: [
      `You are Sam Taylor, a parent who received a call.`,
      `You want to verify which location is calling you.`,
      `Follow these steps:`,
      `1. When the agent introduces themselves, confirm you are Sam.`,
      `2. When asked if you have a minute, say: Sure, but which Code Ninjas location is this? I want to make sure I have the right one.`,
      `3. Listen carefully to what location name the agent gives. It should say ${centreName}.`,
      `4. If they say the correct location (${centreName}), say: Great, that is the one near us. I am interested but need to call back later. Thanks!`,
      `5. If they say a different location, say: Oh, I thought this was ${centreName}. Is this not the ${centreName} location?`,
      `6. End the call politely either way.`,
    ].join(" "),
    expected_outcome_prompt: `Agent correctly identifies itself as calling from Code Ninjas ${centreName} (not East Gwillimbury or any other location). The location name must match exactly: ${centreName}.`,
