}

// ─────────────────────────────────────────────────────────────
// HTTP Helpers
// ─────────────────────────────────────────────────────────────

async function twilioGet<T>(path: string): Promise<T> {
  const url = `${TWILIO_BASE}/Accounts/${TWILIO_SID}${path}`;
  const auth = Buffer.from(`${TWILIO_SID}:${TWILIO_TOKEN}`).toString("base64");
  const res = await fetch(url, {
    headers: { Authorization: `Basic ${auth}` },
  });
  if (!res.ok) {
    const body = await res.text();
    throw new Error(`Twilio GET ${path} → ${res.status}: ${body}`);
  }
  return res.json() as Promise<T>;
}

async function twilioPost<T>(path: string, formData: Record<string, string>): Promise<T> {
  const url = `${TWILIO_BASE}/Accounts/${TWILIO_SID}${path}`;
  const auth = Buffer.from(`${TWILIO_SID}:${TWILIO_TOKEN}`).toString("base64");
  const body = new URLSearchParams(formData).toString();
  const res = await fetch(url, {
    method: "POST",
    headers: {
      Authorization: `Basic ${auth}`,
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body,
  });
  if (!res.ok) {
    const text = await res.text();
    throw new Error(`Twilio POST ${path} → ${res.status}: ${text}`);
  }
  return res.json() as Promise<T>;
}

// Sub-account Twilio helpers — use sub-account credentials
async function subTwilioGet<T>(subSid: string, subToken: string, path: string): Promise<T> {
